file.content:
.sitzplan {
  overflow-x: auto;
}

.sitzplan__reihe {
  display: flex;
  gap: var(--spacing-seat-gap);
  margin-bottom: var(--spacing-seat-gap);
}

.sitzplan__reihen-label {
  position: sticky;
  left: 0;
  z-index: 1;
  flex: 0 0 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--color-surface);
  font-family: var(--font-label-family);
  font-size: var(--font-label-size);
  font-weight: var(--font-label-weight);
  line-height: var(--font-label-line-height);
  color: var(--color-on-surface-variant);
}

.sitzplan__luecke {
  flex: 0 0 32px;
  height: 32px;
}

.sitzplan__skeleton-kachel {
  flex: 0 0 32px;
  height: 32px;
  border-radius: var(--radius-sm);
  background: var(--color-surface-container-high);
}

.buchung__fehler {
  font-family: var(--font-body-lg-family);
  font-size: var(--font-body-lg-size);
  line-height: var(--font-body-lg-line-height);
  color: var(--color-on-error-container);
  background: var(--color-error-container);
  border-radius: var(--radius-default);
  padding: var(--spacing-gutter);
  margin: 0;
}

