    {
        _db.Spielstaetten.Add(new Spielstaette { Id = "V1", Name = "Testspielstätte" });
        _db.Raeume.Add(new Raum { Id = "R1", Name = "Testraum", SpielstaetteId = "V1", Reihen = ["A"], Spalten = 2, GangSpalten = [] });
