        var belegte = sitzplaetze.Where(p => p.Status == "Belegt").Select(p => p.Code).ToList();
        Assert.Equal(["B3", "B4", "C7"], belegte);

        Assert.All(sitzplan.Reihen, reihe => Assert.Equal("Gang", reihe.Positionen.Single(p => p.Spalte == 6).Typ));
